    old_step = @step
    @step = step
    yield
  ensure
    @step = old_step
  end

  def dup(hash)
    new_counter = self.class.new
    new_counter.value = @value
    new_counter.instance_variable_set(:@step, @step)
    new_counter
  end

  def clone(hash)
