class Weight
  attr_reader :amount, :unit

  def initialize(amount, unit)
    @amount = amount
    @unit = unit
  end

  def ==(other)
    return false unless other.is_a?(Weight)
    @amount == other.amount && @unit == other.unit
  end

  def !=(other)
    !(self == other)
  end

  def <(other)
    check_units!(other)
    @amount < other.amount
  end

  def <=(other)
    check_units!(other)
    @amount <= other.amount
  end

  def >(other)
    check_units!(other)
    @amount > other.amount
  end

  def >=(other)
    check_units!(other)
    @amount >= other.amount
  end

  def between?(min, max)
    check_units!(min)
    check_units!(max)
    @amount >= min.amount && @amount <= max.amount
  end

  def clamp(min, max)
    check_units!(min)
    check_units!(max)
    if @amount < min.amount
      Weight.new(min.amount, @unit)
    elsif @amount > max.amount
      Weight.new(max.amount, @unit)
    else
      self
    end
  end

  private

  def check_units!(other)
    raise ArgumentError, "Units must match" unless other.unit == @unit
  end
end
