class KeyStore
  def initialize
    @data = {}
  end

  def store(key, value)
    @data[key] = value
  end

  def fetch(key)
    if @data.key?(key)
      @data[key]
    else
      if block_given?
        yield
      else
        nil
      end
    end
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super
    @hits = 0
    @misses = 0
  end

  def fetch(key)
    if @data.key?(key)
      @hits += 1
    else
      @misses += 1
    end
    super
  end
end
